module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_s0, not_s1;
    wire t0, t1, t2, t3;

    // Invert select signals
    not(not_s0, sel[0]);
    not(not_s1, sel[1]);

    // AND terms for each input
    and(t0, in[0], not_s1, not_s0);
    and(t1, in[1], not_s1, sel[0]);
    and(t2, in[2], sel[1], not_s0);
    and(t3, in[3], sel[1], sel[0]);

    // Combine all terms with OR
    or(out, t0, t1, t2, t3);
endmodule

