module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    function [3:0] decoder;
        input [1:0] in;
        begin
            case (in)
                2'b00: decoder = 4'b0001;
                2'b01: decoder = 4'b0010;
                2'b10: decoder = 4'b0100;
                2'b11: decoder = 4'b1000;
                default: decoder = 4'b0000; // Handles all other cases
            endcase
        end
    endfunction

    assign out = decoder(in);

endmodule

