module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg [1:0] current_state;
reg [3:0] counter;  // Counter to track mod 3 cycles (0-2)

assign state = current_state;

always @(posedge clk) begin
    if (reset) begin
        current_state <= 2'b00;
        counter <= 4'b0000;
    end else begin
        if (current_state == 2'b10) begin
            // Half period: state remains high
            current_state <= 2'b10;
            if (counter[0])  // Increment every 3 cycles (bit 0 set after 3)
                counter <= counter - 1;
        end else begin
            // Full period: toggle state
            current_state <= ~current_state;
            counter <= 4'b0000;
        end
    end
end

endmodule

