module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg [1:0] current_state, next_state;

parameter [1:0] ZERO = 2'b00,
                 ONE = 2'b01,
                 TWO = 2'b10;

// State register with synchronous reset
always @(posedge clk) begin
    if (reset)
        current_state <= ZERO;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        ZERO: next_state = ONE;
        ONE: next_state = TWO;
        TWO: next_state = ZERO;
        default: next_state = ZERO;
    endcase
end

// Output assignment
assign state = current_state;

endmodule

