module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg [11:0] internal_counter;

always @(posedge clk) begin
    if (reset) begin
        internal_counter <= 12'b0;
    end else begin
        internal_counter[11:10] <= internal_counter[11:10] + 1;
        if (internal_counter[11:10] == 2'b11) begin
            internal_counter[9:0] <= 10'b0;
        end else begin
            internal_counter[9:0] <= internal_counter[9:0] + 1;
        end
    end
end

assign state = internal_counter[11:10];

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State definitions
    localparam [1:0] stateA = 2'b00,
                     stateB = 2'b01,
                     stateC = 2'b10;

    reg [1:0] current_state, next_state;

    // State register
    always @(posedge clk) begin
        if (reset)
            current_state <= stateA;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            stateA: next_state = stateB;
            stateB: next_state = stateC;
            stateC: next_state = stateA;
            default: next_state = stateA;
        endcase
    end

    // Output logic
    always @(*) begin
        case (current_state)
            stateA: light = 3'b100;
            stateB: light = 3'b010;
            stateC: light = 3'b001;
            default: light = 3'b100;
        endcase
    end

endmodule

