module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State definitions
    localparam RED   = 2'b00,
               GREEN = 2'b01,
               BLUE  = 2'b10;

    reg [1:0] current_state, next_state;

    // State transition logic
    always @(*) begin
        case (current_state)
            RED:   next_state = clk ? GREEN : RED;
            GREEN: next_state = clk ? BLUE : GREEN;
            BLUE:  next_state = clk ? RED : BLUE;
            default: next_state = RED;
        endcase
    end

    // State register with synchronous reset
    always @(posedge reset) begin
        if (reset)
            current_state <= RED;
        else
            current_state <= next_state;
    end

    // Output logic
    assign light[0] = (current_state == RED);
    assign light[1] = (current_state == GREEN);
    assign light[2] = (current_state == BLUE);

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

reg [2:0] state;
wire [2:0] D;

// Next state logic
assign D[0] = ~state[1] & ~state[2];
assign D[1] = ~state[0] & ~state[2];
assign D[2] = ~state[0] & ~state[1];

// State transition on rising clock edge
always @(posedge clk) begin
    state <= D;
end

// Output logic
assign light[0] = ~state[2] & ~state[1];
assign light[1] = state[0] & ~state[1];
assign light[2] = state[0] | state[1];

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

// Define state parameters
localparam [1:0] RESET_STATE = 2'b00,
                 WAIT_STATE  = 2'b01,
                 FETCH_STATE = 2'b10,
                 LOAD_STATE  = 2'b11;

reg [1:0] current_state, next_state;

// State register with asynchronous reset
always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= RESET_STATE;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        RESET_STATE: 
            next_state = WAIT_STATE;
        WAIT_STATE: 
            next_state = up_request ? FETCH_STATE : WAIT_STATE;
        FETCH_STATE: 
            next_state = down_request ? LOAD_STATE : FETCH_STATE;
        LOAD_STATE: 
            next_state = WAIT_STATE;
        default: 
            next_state = RESET_STATE;
    endcase
end

// Output assignment
assign state = current_state;

endmodule

