module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    reg [1:0] Q, next_Q;
    parameter S0 = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10,
              S3 = 2'b11;

    always @(posedge clk or posedge reset) begin
        if (reset) Q <= S0;
        else Q <= next_Q;
    end

    always @(*) begin
        case (Q)
            S0: next_Q = (up_request) ? S1 : S0;
            S1: begin
                if (!up_request) next_Q = S0;
                else next_Q = (down_request) ? S2 : S1;
            end
            S2: next_Q = (!up_request) ? S3 : S2;
            S3: begin
                if (up_request) next_Q = S0;
                else next_Q = (down_request) ? S2 : S3;
            end
            default: next_Q = S0;
        endcase
    end

    assign state = Q;
endmodule

