module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State encoding parameters
    localparam [1:0] STATE_0 = 2'b00,
                     STATE_1 = 2'b01,
                     STATE_2 = 2'b10;

    reg [1:0] state_reg, state_next;

    // State register with synchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= STATE_0;
        end else begin
            state_reg <= state_next;
        end
    end

    // Next state combinational logic
    always @(*) begin
        case (state_reg)
            STATE_0: begin
                if (up_request)
                    state_next = STATE_1;
                else if (down_request)
                    state_next = STATE_2;
                else
                    state_next = STATE_0;
            end
            STATE_1: begin
                if (down_request)
                    state_next = STATE_2;
                else if (up_request)
                    state_next = STATE_0;
                else
                    state_next = STATE_1;
            end
            STATE_2: begin
                if (up_request)
                    state_next = STATE_0;
                else if (down_request)
                    state_next = STATE_1;
                else
                    state_next = STATE_2;
            end
            default: state_next = STATE_0;
        endcase
    end

    // Output assignment
    assign state = state_reg;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

reg [1:0] current_state, next_state;

// State register with synchronous reset
always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= 2'b00;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    if (coin_inserted) begin
        case (current_state)
            2'b00: next_state = item_selected ? 2'b01 : 2'b00;
            2'b01: next_state = item_selected ? 2'b10 : 2'b00;
            2'b10: next_state = item_selected ? 2'b11 : 2'b01;
            2'b11: next_state = item_selected ? 2'b11 : 2'b10;
            default: next_state = 2'b00;
        endcase
    end else begin
        next_state = current_state;
    end
end

// Output current state
assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State definitions
    parameter [1:0] S0 = 2'b00,
                    S1 = 2'b01,
                    S2 = 2'b10,
                    S3 = 2'b11;

    reg [1:0] state;

    // State transitions
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S0;
        end else begin
            case (state)
                S0: if (coin_inserted) state <= S1;
                S1: if (coin_inserted) state <= S3;
                S3: if (item_selected) state <= S2;
                S2: if (item_selected) state <= S1;
                default: state <= S0;
            endcase
        end
    end

    // Output assignment
