module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State definitions
    localparam [1:0] STATE_AWAITSTART_0 = 2'b00,
                     STATE_AWAITSTART_1 = 2'b01,
                     STATE_STARTGAME_0  = 2'b10,
                     STATE_STARTGAME_1  = 2'b11;

    reg [1:0] current_state, next_state;

    // Sequential state update
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= STATE_AWAITSTART_0;
        else
            current_state <= next_state;
    end

    // Combinational next state logic
    always @(*) begin
        next_state = current_state;
        if (coin_inserted) begin
            case (current_state)
                STATE_AWAITSTART_0: next_state = STATE_AWAITSTART_1;
                STATE_AWAITSTART_1: next_state = STATE_STARTGAME_0;
                STATE_STARTGAME_0: next_state = item_selected ? STATE_STARTGAME_1 : STATE_STARTGAME_0;
                STATE_STARTGAME_1: next_state = STATE_STARTGAME_1;
                default: next_state = STATE_AWAITSTART_0;
            endcase
        end
    end

    // Output assignment
    assign state = current_state;

endmodule

module vending_machine (
