    if (reset) begin
        r_Switch <= 2'b00;
    end else begin
        if (coin_inserted) begin
            // Update bit 0 based on item_selected
            r_Switch[0] <= (r_Switch[0] == 1'b0) ? item_selected : 1'b0;
        end
        if (item_selected) begin
            // Update bit 1 based on coin_inserted
            r_Switch[1] <= (r_Switch[1] == 1'b0) ? coin_inserted : 1'b0;
        end
    end
end

