                     STATE_1 = 2'b01,
                     STATE_2 = 2'b10,
                     STATE_X = 2'b11;

    reg [1:0] state;

    // State transitions
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= STATE_0;
        end else begin
            case (state)
                STATE_0: if (coin_inserted) state <= STATE_1;
                STATE_1: if (item_selected) state <= STATE_2;
                STATE_2: if (coin_inserted) state <= STATE_X;
                STATE_X: state <= STATE_X;
                default: state <= STATE_0;
            endcase
        end
    end

    assign state = state;

endmodule

