wire [3:0] digit2 = (in_0[11:8]  >= 4'd10) ? 4'd1 : 4'd0;
wire [3:0] digit1 = (in_0[7:4]   >= 4'd10) ? 4'd1 : 4'd0;
wire [3:0] digit0 = (in_0[3:0]   >= 4'd10) ? 4'd1 : 4'd0;

wire valid = (digit3 <= 9) && (digit2 <= 9) && (digit1 <= 9) && (digit0 <= 9);

