always @* begin
    approx = 8'b0;
    if (in_0[15]) begin // Negative input
        approx = -8'd16;
        for (integer i = 14; i >= 0; i = i - 1) begin
            if ((approx + (1 << i)) <= in_0[14:0])
                approx = approx + (1 << i);
        end
    end else begin // Positive input
        approx = 8'd16;
        for (integer i = 14; i >= 0; i = i - 1) begin
            if ((approx - (1 << i)) <= in_0[14:0])
                approx = approx - (1 << i);
        end
    end
end

assign out = approx;

