module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);

    // Sign-extend inputs to 9 bits
    wire signed [8:0] in1_ext = {a[7], a};
    wire signed [8:0] in2_ext = {b[7], b};

    // Bit 0: XNOR of LSBs
    assign out[0] = ~(in1_ext[0] ^ in2_ext[0]);

    // Bit 1: XOR of extended LSBs
    assign out[1] = in1_ext[1] ^ in2_ext[1];

    // Bits 2-8: Custom logic combining XOR and intermediate AND/OR operations
    assign out[2] = (in1_ext[2] ^ in2_ext[2]) & (in1_ext[1] | in2_ext[1]);
    assign out[3] = (in1_ext[3] ^ in2_ext[3]) | (in1_ext[2] & in2_ext[2]);
    assign out[4] = ~(in1_ext[4] ^ in2_ext[4]) & (in1_ext[3] | in2_ext[3]);
    assign out[5] = (in1_ext[5] ^ in2_ext[5]) | (in1_ext[4] & in2_ext[4]);
    assign out[6] = (in1_ext[6] ^ in2_ext[6]) & (in1_ext[5] | in2_ext[5]);
    assign out[7] = (in1_ext[7] ^ in2_ext[7]) | (in1_ext[6] & in2_ext[6]);
    assign out[8] = (in1_ext[8] ^ in2_ext[8]) & (in1_ext[7] | in2_ext[7]);

endmodule

