    assign a[13] = a[3] & b[1];
    assign a[14] = a[3] & b[2];
    assign a[15] = a[3] & b[3];

    // Calculate carry signals c[7:0]
    wire [7:0] c;
    assign c[0] = a[0] | a[1] | a[2] | a[3];
    assign c[1] = a[4] | a[5] | a[6] | c[0];
    assign c[2] = a[8] | a[9] | a[10] | c[1];
    assign c[3] = a[12] | a[13] | a[14] | c[2];
    assign c[4] = a[0] | a[5] | a[10] | c[3];
    assign c[5] = a[4] | a[9] | a[14] | c[4];
    assign c[6] = a[8] | a[13] | a[7] | c[5];
    assign c[7] = a[12] | a[15] | a[3] | c[6];

    // Compute output bits out[7:0]
    assign out[0] = a[0] ^ c[0];
    assign out[1] = a[1] ^ c[1];
    assign out[2] = a[2] ^ c[2];
