    wire pp0_2 = a[0] & b[2];
    wire pp0_3 = a[0] & b[3];

    wire pp1_0 = a[1] & b[0];
    wire pp1_1 = a[1] & b[1];
    wire pp1_2 = a[1] & b[2];
    wire pp1_3 = a[1] & b[3];

    wire pp2_0 = a[2] & b[0];
    wire pp2_1 = a[2] & b[1];
    wire pp2_2 = a[2] & b[2];
    wire pp2_3 = a[2] & b[3];

    wire pp3_0 = a[3] & b[0];
    wire pp3_1 = a[3] & b[1];
    wire pp3_2 = a[3] & b[2];
    wire pp3_3 = a[3] & b[3];

    // Column 0: no shift, add directly
    assign out[0] = pp0_0;

    // Column 1: sum of partial products at distance 1
    assign out[1] = pp0_1 ^ pp1_0;

    // Column 2: sum of partial products at distance 2
    assign out[2] = pp0_2 ^ pp1_1 ^ pp2_0;

    // Column 3: sum of partial products at distance 3
    assign out[3] = pp0_3 ^ pp1_2 ^ pp2_1 ^ pp3_0;

    // Column 4: sum of partial products at distance 4
    assign out[4] = pp1_3 ^ pp2_2 ^ pp3_1;

    // Column 5: sum of partial products at distance 5
    assign out[5] = pp2_3 ^ pp3_2;

    // Column 6: sum of partial products at distance 6
    assign out[6] = pp3_3;

    // Column 7: no partial products, sum is 0
    assign out[7] = 1'b0;

endmodule

