module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] eq;
    wire [3:0] gt;
    wire [3:0] lt;

    // Equality check (XNOR each bit)
    assign eq = a ~^ b;

    // eq is high if all bits are equal
    assign eq = &eq;

    // Greater than check ( propagate and OR)
    assign gt[0] = a[0] > b[0];
    assign gt[1] = ~(eq[1] & gt[0]);
    assign gt[2] = ~(eq[2] & gt[1]);
    assign gt[3] = ~(eq[3] & gt[2]);
    assign lt = gt[3];

    // Less than check (propagate and AND)
    assign lt[0] = a[0] < b[0];
    assign lt[1] = ~(eq[1] & lt[0]);
    assign lt[2] = ~(eq[2] & lt[1]);
    assign lt[3] = ~(eq[3] & lt[2]);
    assign gt = lt[3];
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] eq;
    wire [3:0] gt;
    wire [3:0] lt;
    wire all_eq;

    // Equality check (XNOR each bit)
    xnor(eq[0], a[0], b[0]);
    xnor(eq[1], a[1], b[1]);
    xnor(eq[2], a[2], b[2]);
    xnor(eq[3], a[3], b[3]);
    assign all_eq = &eq;  // All bits equal if AND is true

    // Greater than check (propagate and check higher bits)
    and(gt[3], a[3], b[3]);
    and(gt[2], a[2], eq[3]);
    and(gt[1], a[1], eq[3], eq[2]);
    and(gt[0], a[0], eq[3], eq[2], eq[1]);
    or(eq, gt[3], gt[2], gt[1], gt[0]);

    // Less than check (propagate and check higher bits)
    and(lt[3], b[3], a[3]);
    and(lt[2], b[2], eq[3]);
    and(lt[1], b[1], eq[3], eq[2]);
    and(lt[0], b[0], eq[3], eq[2], eq[1]);
    or(lt, lt[3], lt[2], lt[1], lt[0]);

    // Final result
    assign gt = all_eq ? 1'b0 : (eq ? 1'b1 : (lt ? 1'b0 : 1'b1));
endmodule

