module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);

reg [7:0] q_reg;
wire [7:0] t_input;

// Generate T inputs for each bit
assign t_input[0] = 1'b1; // LSB always toggles
genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin : t_gen
        assign t_input[i] = &q_reg[i-1:0]; // AND of higher bits
    end
endgenerate

// Update flip-flops on positive clock edge
always @(posedge clk) begin
    if (rst) begin
        q_reg <= 8'b0;
    end else begin
        for (integer j = 0; j < 8; j = j + 1) begin
            q_reg[j] <= q_reg[j] ^ t_input[j];
        end
    end
end

assign count = q_reg;

endmodule

