genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin : gen_toggle
        assign t[i] = &q_reg[i-1:0];
    end
endgenerate

always @(posedge clk) begin
    if (rst) begin
        q_reg <= 8'b0;
    end else begin
        for (integer j = 0; j < 8; j = j + 1) begin
            q_reg[j] <= q_reg[j] ^ t[j];
        end
    end
end

assign count = q_reg;

