module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] stateA = 2'b00,
                   stateB = 2'b01,
                   stateC = 2'b10,
                   stateD = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge resetn) begin
    if (clk)
      current_state <= stateA;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      stateA: begin
        if (r[0])
          next_state = stateB;
        else if (r[1])
          next_state = stateC;
        else if (r[2])
          next_state = stateD;
        else
          next_state = stateA;
      end
      stateB: begin
        if (r[0])
          next_state = stateB;
        else if (r[1])
          next_state = stateC;
        else if (r[2])
          next_state = stateD;
        else
          next_state = stateB;
      end
      stateC: begin
        if (r[0])
          next_state = stateB;
        else if (r[1])
          next_state = stateC;
        else if (r[2])
          next_state = stateD;
        else
          next_state = stateC;
      end
      stateD: begin
        if (r[0])
          next_state = stateB;
        else if (r[1])
          next_state = stateC;
        else if (r[2])
          next_state = stateD;
        else
          next_state = stateD;
      end
      default: next_state = stateA;
    endcase
  end

  assign g = (current_state == stateD) ? 3'b111 : 3'b000;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  // Define states
  localparam [1:0] state_A = 2'b00,
                   state_B = 2'b01,
                   state_C = 2'b10,
                   state_D = 2'b11;

  reg [1:0] current_state, next_state;

  // State register
  always @(posedge resetn) begin
    if (clk)
      current_state <= state_A;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      state_A: begin
        if (r[0])
          next_state = state_B;
        else if (r[1])
          next_state = state_C;
        else if (r[2])
          next_state = state_D;
        else
          next_state = state_A;
      end
      state_B: begin
        if (r[0])
          next_state = state_B;
        else if (r[1])
          next_state = state_C;
        else if (r[2])
          next_state = state_D;
        else
          next_state = state_B;
      end
      state_C: begin
        if (r[0])
          next_state = state_B;
        else if (r[1])
          next_state = state_C;
        else if (r[2])
          next_state = state_D;
        else
          next_state = state_C;
      end
      state_D: begin
        if (r[0])
          next_state = state_B;
        else if (r[1])
          next_state = state_C;
        else if (r[2])
          next_state = state_D;
        else
          next_state = state_D;
      end
      default: next_state = state_A;
    endcase
  end

  // Output logic
  assign g = (current_state == state_D) ? 3'b111 :
                 (current_state == state_C) ? 3'b100 :
                 (current_state == state_B) ? 3'b011 :
                 3'b000;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [2:0] current_state;

  always @(posedge resetn) begin
    if (clk) begin
      current_state <= 3'b000;
    end else begin
      case (current_state)
        3'b000: current_state <= (r[0]) ? 3'b001 : 3'b000;
        3'b001: current_state <= (r[0]) ? 3'b010 : 3'b000;
        3'b010: current_state <= (r[1]) ? 3'b011 : 3'b001;
        3'b011: current_state <= (r[1]) ? 3'b100 : 3'b010;
        3'b100: current_state <= (r[2]) ? 3'b101 : 3'b011;
        3'b101: current_state <= (r[2]) ? 3'b110 : 3'b100;
        3'b110: current_state <= (r[0]) ? 3'b111 : 3'b101;
        3'b111: current_state <= (r[1]) ? 3'b000 : 3'b110;
        default: current_state <= 3'b000;
      endcase
    end
  end

  assign g = current_state;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10,
             S3 = 2'b11;

  reg [1:0] state_reg, state_next;

  // State register
  always @(posedge resetn) begin
    if (clk)
      state_reg <= S0;
    else
      state_reg <= state_next;
  end

  // Next state logic
  always @(*) begin
    case (state_reg)
      S0: state_next = r[0] ? S1 : S0;
      S1: state_next = r[1] ? S2 : S1;
      S2: state_next = r[2] ? S3 : S2;
      S3: state_next = S0; // Transition to S0 regardless of input
      default: state_next = S0;
    endcase
  end

  // Output logic
  assign g = (state_reg == S3) ? 3'b100 :
                      (state_reg == S0) ? {1'b0, r} :
                      3'b000;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  parameter GN = 2'b00,
           RY = 2'b01,
           RYB = 2'b10,
           RB = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge resetn) begin
    if (clk)
      current_state <= GN;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      GN: next_state = (r == 3'b000) ? RY : GN;
      RY: next_state = (r == 3'b001) ? RB : RY;
      RB: next_state = (r == 3'b010) ? RYB : RB;
      RYB: next_state = (r == 3'b011) ? GN : RYB;
      default: next_state = GN;
    endcase
  end

  assign g = (current_state == RY) ? r :
                   (current_state == RB) ? 3'b001 :
                   (current_state == RYB) ? 3'b010 :
                   3'b000;

endmodule

