  assign selected_data = (sel_b1 && !sel_b2) ? a :
                         (!sel_b1 && sel_b2) ? b :
                         1'bz; // High-Z when both enables are inactive

  // Tri-state buffer to output the selected data
  always @(*) begin
    out_always = (out_assign) ? selected_data : 1'bz;
