module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  // Local parameter for delay value
  localparam DELAY_VALUE = 1;

  // Registers for exact delay
  reg [DELAY_VALUE-1:0] delay_reg_c1;
  reg [DELAY_VALUE-1:0] delay_reg_c2;

  // Rounding register
  reg rounding_reg;

  // Combine inputs with delay (c1 + c2)
  wire [2*DELAY_VALUE-1:0] sum_delay = arrived + gas_tank_empty;

  // Update delay registers on negative edge of cpu_overheated
  always @(negedge cpu_overheated) begin
    delay_reg_c1 <= sum_delay;
    if (DELAY_VALUE > 1) begin
      delay_reg_c2 <= sum_delay;
    end
  end

  // Calculate sum without delay (cpu_overheated + 1)
  wire sum_no_delay = cpu_overheated + 1;

  // Rounding logic
  always @(*) begin
    if (DELAY_VALUE > 0) begin
      rounding_reg = sum_no_delay[2*DELAY_VALUE-1] ^ delay_reg_c1[DELAY_VALUE-1];
    end else begin
      rounding_reg = sum_no_delay[0];
    end
  end

  // Assign outputs based on rounding register
  always @(*) begin
    shut_off_computer = rounding_reg ? sum_no_delay : cpu_overheated;
    keep_driving = rounding_reg ? sum_delay : arrived;
  end

endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  parameter S0 = 1'b0;
  parameter S1 = 1'b1;

  reg state = S0;

  always @(posedge cpu_overheated) begin
    case (state)
      S0: state <= S1;
      S1: state <= S0;
      default: state <= S0;
    endcase
  end

  always @(*) begin
    if (state == S0) begin
      shut_off_computer = 1'b0;
      if (!gas_tank_empty) begin
        keep_driving = 1'b1;
      end else begin
        keep_driving = arrived;
      end
    end else begin
      shut_off_computer = 1'b1;
      keep_driving = 1'b0;
    end
  end

endmodule

