  output out_and,
  output out_or,
  output out_xor
);

  wire [1:0] select;

  // 2-bit encoder using case statement
  always @(*) begin
    case (in[3:2])
      2'b00: select = 2'b00;
      2'b01: select = 2'b01;
      2'b10: select = 2'b10;
      2'b11: select = 2'b11;
    endcase
  end

  // Generate out_and (in[1] AND in[0])
  assign out_and = in[1] & in[0];

  // Generate out_or (OR of inverted in[3], in[2], in[1], in[0])
  assign out_or = (~in[3]) | in[2] | in[1] | in[0];

  // Generate out_xor using XOR and NOT operations
  wire b1_inv = ~in[1];
  wire b0_inv = ~in[0];
  wire a1_b0 = in[1] & b0_inv;
  wire a1_b1 = in[1] & in[0];
  wire a2_b0 = in[2] & b0_inv;
  wire a2_b1 = in[2] & in[0];
  wire a3_or = in[3] | b1_inv;
  wire a3_and = a3_or & in[2];
  wire a3_or2 = a3_and | a1_b1;
  wire a3_nor = ~(a3_or2 | a2_b0);
  assign out_xor = a3_or2 ^ a3_nor;

