  input d,
  input r,
  output logic q
);

  // Define state parameters
  localparam S0 = 1'b0;
  localparam S1 = 1'b1;

  reg current_state;

  // State transition logic
  always @(posedge clk) begin
    if (r)
      current_state <= S0;
    else begin
      case (current_state)
        S0: current_state <= d ? S1 : S0;
        S1: current_state <= d ? S1 : S0;
