module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  reg [2:0] state, next_state;

  localparam S0 = 3'd0,
             S1 = 3'd1,
             S2 = 3'd2,
             S3 = 3'd3,
             S4 = 3'd4;

  // State transition
  always @(posedge clk) begin
    if (reset)
      state <= S0;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      S0: next_state = w ? S1 : S0;
      S1: next_state = w ? S1 : S2;
      S2: next_state = w ? S1 : S3;
      S3: next_state = w ? S4 : S0;
      S4: next_state = w ? S1 : S2;
      default: next_state = S0;
    endcase
  end

  // Output logic
  assign z = (state == S4) || (state == S3 && w);

endmodule

