  wire b_xor_c = b ^ c;
  wire a_and_b_xor_c = a & b_xor_c;
  wire sum = a ^ b_xor_c ^ c;
  wire carry = a_and_b_xor_c | (b & c);

  assign out = {sum, carry};

endmodule

