module TopModule (
  input clk,
  input shift_ena,
  input count_ena,
  input data,
  output reg [3:0] q
);

  always @(posedge clk) begin
    if (shift_ena && count_ena) begin
      q <= 4'b0000;
    end else if (shift_ena) begin
      q <= (data) ? 4'b1000 : 4'b0111;
    end else if (count_ena) begin
      if (q == 4'b0000)
        q <= 4'b1000;
      else
        q <= q - 1;
    end
  end

endmodule

module TopModule (
  input clk,
  input shift_ena,
  input count_ena,
  input data,
  output reg [3:0] q
);

  always @(posedge clk) begin
    case ({shift_ena, count_ena})
      2'b00: q <= q;
      2'b10: q <= {data, q[3:1]};
      2'b01: q <= {q[2:0], 1'b0};
      2'b11: q <= {q[2:0], 1'b1};
      default: q <= q;
    endcase
  end

endmodule

module TopModule (
  input clk,
  input shift_ena,
  input count_ena,
  input data,
  output reg [3:0] q
);

  always @(posedge clk) begin
    case ({shift_ena, count_ena})
      2'b00: q <= q;
      2'b01: q <= {data, q[3:1]};
      2'b10: q <= {q[2:0], 1'b0};
      2'b11: q <= 4'b0;
    endcase
  end

endmodule

