module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out,
  output out_n
);

wire c1, c2;
wire temp1, temp1_inv, temp2, temp2_inv;

// Calculate c1 = b & ~a
nand nand1(temp1, b, a);
not not1(temp1_inv, temp1);
nand nand2(c1, temp1_inv, temp1_inv);

// Calculate c2 = d & ~c
nand nand3(temp2, d, c);
not not2(temp2_inv, temp2);
nand nand4(c2, temp2_inv, temp2_inv);

// Calculate out = c1 | c2 using NAND
nand nand5(out, c1, c2);

// Calculate out_n = ~out using NAND
nand nand6(out_n, out, out);

endmodule

