module TopModule (
  input clk,
  input areset,
  input x,
  output z
);

  reg [1:0] current_state;
  reg [1:0] next_state;

  parameter state_0 = 2'b00;
  parameter state_1 = 2'b01;
  parameter state_2 = 2'b10;

  // State transition logic
  always @(*) begin
    case (current_state)
      state_0: next_state = x ? state_1 : state_0;
      state_1: next_state = x ? state_2 : state_0;
      state_2: next_state = x ? state_2 : state_0;
      default: next_state = state_0;
    endcase
  end

  // State register with asynchronous areset
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= state_0;
    end else begin
      current_state <= next_state;
    end
  end

  // Output logic
  assign z = (current_state == state_1) ? x : ~x;

endmodule

