      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      A: next_state = reset ? B : A;
      B: next_state = (counter == 3'd4) ? C : B;
      C: next_state = reset ? C : A;
      default: next_state = A;
    endcase
  end

  // Counter for state B
  always @(posedge clk) begin
    if (in)
      counter <= 0;
    else if (current_state != B)
      counter <= 0;
    else if (counter < 3'd4)
      counter <= counter + 1;
  end

  // Duration counter for done
  always @(posedge clk) begin
    if (in)
      dur_counter <= 0;
    else if (current_state == B && !reset)
      dur_counter <= dur_counter + 1;
  end

  // Output logic
  always @(posedge clk) begin
    if (in)
      clk_out_reg <= 0;
    else if (current_state == B && !reset && dur_counter == 3'd4)
      clk_out_reg <= 1;
    else
      clk_out_reg <= 0;
  end

  assign done = clk_out_reg;

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  localparam IDLE = 2'b00;
  localparam CHECK = 2'b01;
  localparam ADD = 2'b10;

  reg [1:0] current_state, next_state;
  reg [2:0] counter;
  reg [2:0] max_count;

  // State transition
  always @(posedge clk) begin
    if (in) begin
      current_state <= IDLE;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = reset ? CHECK : IDLE;
      CHECK: begin
        if (counter == max_count)
          next_state = (reset) ? ADD : IDLE;
        else
          next_state = CHECK;
      end
      ADD: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

  // Max count determination
  always @(posedge clk) begin
    if (in) begin
      max_count <= 3'b0;
    end else begin
      case (current_state)
        IDLE: max_count <= 3'b0;
        CHECK: max_count <= (counter == max_count) ? 3'b0 : CHECK;
        ADD: max_count <= 3'b0;
        default: max_count <= 3'b0;
      endcase
    end
  end

  // Counter control
  always @(posedge clk) begin
    if (in) begin
      counter <= 3'b0;
    end else begin
      case (current_state)
        IDLE: counter <= 3'b0;
        CHECK: if (counter == max_count)
                  counter <= 3'b0;
                else
                  counter <= counter + 1;
        ADD: counter <= 3'b0;
        default: counter <= 3'b0;
      endcase
    end
  end

  // Valid output assignment
  assign done = (current_state == ADD);

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);
  localparam [1:0] RESET = 2'b00,
                   START  = 2'b01,
                   COUNT  = 2'b10;

  reg [1:0] state, next_state;
  reg [2:0] counter;
  reg out_reg;

  // State register
  always @(posedge clk) begin
    if (reset)
      state <= RESET;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      RESET: next_state = in ? START : RESET;
      START: next_state = in ? COUNT : START;
      COUNT: next_state = (counter == 3'd7) ? RESET : COUNT;
      default: next_state = RESET;
    endcase
  end

  // Counter logic
  always @(posedge clk) begin
    if (reset)
      counter <= 3'b0;
    else if (state == COUNT)
      counter <= counter + 1;
    else
      counter <= 3'b0;
  end

  // Output logic
  always @(posedge clk) begin
    if (reset)
      out_reg <= 1'b0;
    else
      out_reg <= (state == START) ? 1'b1 : 
                 (state == COUNT) ? (counter[2] ^ counter[0]) : 
                 1'b0;
  end

  assign done = out_reg;

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  localparam [1:0] S0 = 2'b00,
                   S1 = 2'b01,
                   S2 = 2'b10,
                   S3 = 2'b11;

  reg [1:0] current_state;
  reg [1:0] next_state;
  reg [2:0] counter;
  reg [1:0] max_count;

  always @(*) begin
    case (current_state)
      S0: max_count = in ? 3'd1 : 3'd0;
      S1: max_count = in ? 3'd3 : 3'd1;
      S2: max_count = in ? 3'd5 : 3'd3;
      S3: max_count = in ? 3'd7 : 3'd5;
      default: max_count = 3'd0;
    endcase
  end

  always @(posedge clk) begin
    current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      S0: next_state = in ? S1 : S0;
      S1: next_state = in ? S2 : S1;
      S2: next_state = in ? S3 : S2;
      S3: next_state = in ? S0 : S3;
      default: next_state = S0;
    endcase
  end

  always @(posedge clk) begin
    if (reset)
      counter <= 3'd0;
    else if (current_state != next_state)
      counter <= 3'd0;
    else if (counter < max_count)
      counter <= counter + 3'd1;
  end

  assign done = (counter == max_count);

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  localparam IDLE = 2'b00;
  localparam PRESSED = 2'b01;
  localparam DEBOUNCE = 2'b10;

  reg [1:0] state, next_state;
  reg [2:0] debounce_counter;
  reg pbtn_prev;
  reg keyout_reg;

  always @(posedge clk) begin
    state <= next_state;
  end

  always @* begin
    case (state)
      IDLE: next_state = (pbtn_prev && !in) ? PRESSED : IDLE;
      PRESSED: next_state = DEBOUNCE;
      DEBOUNCE: begin
        if (in)
          next_state = IDLE;
        else if (debounce_counter == 3'd7)
          next_state = IDLE;
        else
          next_state = DEBOUNCE;
      end
      default: next_state = IDLE;
    endcase
  end

  always @(posedge clk) begin
    pbtn_prev <= in;
  end

  always @(posedge clk) begin
    if (state == DEBOUNCE)
      debounce_counter <= debounce_counter + 1;
    else
      debounce_counter <= 3'd0;
  end

  always @(posedge clk) begin
    if (state == DEBOUNCE && in && debounce_counter == 3'd7)
      keyout_reg <= 1'b0;
    else if (state == PRESSED && reset)
      keyout_reg <= 1'b1;
    else
      keyout_reg <= keyout_reg;
  end

  assign done = keyout_reg;

endmodule

