module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // State definitions
  localparam [1:0] IDLE = 2'b00,
                   PLAY = 2'b01,
                   WIN  = 2'b10,
                   LOSE = 2'b11;

  reg [1:0] current_state, next_state;

  // State register with asynchronous reset
  always @(posedge clk, posedge areset) begin
    if (areset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = bump_left ? PLAY : IDLE;
      PLAY: begin
        if (ground)
          next_state = WIN;
        else if (bump_right)
          next_state = LOSE;
        else
          next_state = PLAY;
      end
      WIN: next_state = WIN;
      LOSE: next_state = LOSE;
      default: next_state = IDLE;
    endcase
  end

  // Output logic
  assign walk_left = (current_state == IDLE);
  assign walk_right = (current_state == LOSE);
  assign aaah = (current_state == IDLE || current_state == PLAY);

endmodule

module TopModule (
