        next_state = (bump_right) ? GNT0 : 
                    (ground) ? GNT1 : WAIT;
      end
      GNT0: next_state = (bump_right) ? GNT0 : WAIT;
      GNT1: next_state = (bump_right || ground) ? GNT0 : GNT1;
      GNT2: next_state = (bump_left || bump_right || ground) ? GNT0 : GNT2;
      default: next_state = WAIT;
    endcase
  end

  // Output logic
  assign walk_left = (current_state == GNT0);
  assign walk_right = (current_state == GNT1);
