  input reset,
  input data,
  output start_shifting
);

  reg [2:0] shift_reg;
  reg alarm_reg;

  always @(posedge clk) begin
    if (data) begin
      shift_reg <= 3'b0;
      alarm_reg <= 1'b0;
    end else begin
      shift_reg <= {shift_reg[1:0], reset};
      if ({shift_reg[1:0], reset} == 3'b111) begin
        alarm_reg <= 1'b1;
      end else if (alarm_reg && ({shift_reg[1:0], reset} == 3'b000)) begin
        alarm_reg <= 1'b0;
      end
    end
  end

  assign start_shifting = alarm_reg;

endmodule

module TopModule (
