  input reset,
  input data,
  output start_shifting
);

  reg [2:0] samples;
  reg pull_up_reg;

  always @(posedge clk) begin
    if (reset) begin
      samples <= 3'b000;
      pull_up_reg <= 1'b0;
    end else begin
      // Update the shift register with the new sample
      samples <= {samples[1:0], data};
      // Update pull-up state if all three samples are the same
      if (data && (samples == 3'b111))
        pull_up_reg <= 1'b1;
      else if (!data && (samples == 3'b000))
        pull_up_reg <= 1'b0;
    end
  end

  assign start_shifting = pull_up_reg;

endmodule

module TopModule (
