    end else begin
      // Update shift register with current data input
      shift_reg <= {shift_reg[1:0], data};

      // Check if current sequence is 0_0_1 (valid pattern)
      if ({shift_reg[1:0], data} == 3'b001) begin
        warning_flashed <= 1'b1;
      end

      // Reset if all inputs are reset (assumed when data=1 and reset=1)
      if (data && reset) begin
        shift_reg <= 3'b0;
        warning_flashed <= 1'b0;
      end
    end
  end

  // Output is high when warning has been flashed
  assign start_shifting = warning_flashed;

