module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  // Define states
  localparam [2:0] 
    IDLE  = 3'b000,
    S0    = 3'b001,
    S1    = 3'b010,
    S2    = 3'b011,
    S3    = 3'b100,
    S4    = 3'b101,
    S4A   = 3'b110,
    S4B   = 3'b111;

  reg [2:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (resetn)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = x ? S0 : IDLE;
      S0:   next_state = x ? S1 : S0;
      S1:   next_state = y ? S2 : S1;
      S2:   next_state = y ? S3 : S2;
      S3:   next_state = y ? S4 : S3;
      S4:   next_state = y ? S4A : S4;
      S4A:  next_state = x ? S0 : S4B;
      S4B:  next_state = y ? S2 : S4B;
      default: next_state = IDLE;
    endcase
  end

  // Output logic
  assign f = (current_state == S4A);
  assign g = (current_state == S4B);

endmodule

module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  // Define states
  parameter HLT      = 3'd0;
  parameter CLRLCD   = 3'd1;
  parameter WAIT     = 3'd2;
  parameter INC_PTR  = 3'd3;
  parameter PUSH     = 3'd4;
  parameter POP      = 3'd5;
  parameter HALT_2   = 3'd6;

  reg [2:0] state, next_state;

  // State register
  always @(posedge clk) begin
    if (resetn)
      state <= HLT;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      HLT:      next_state = HLT;
      CLRLCD:   next_state = WAIT;
      WAIT:     next_state = (x) ? CLRLCD : (y) ? INC_PTR : WAIT;
      INC_PTR:  next_state = PUSH;
      PUSH:     next_state = POP;
      POP:      next_state = (x) ? POP : HALT_2;
      HALT_2:   next_state = HLT;
      default:  next_state = HLT;
    endcase
  end

  // Output logic
  assign f = (state == CLRLCD);
  assign g = (state == POP);

endmodule

module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  // Define states for f FSM
  localparam [2:0] IDLE_A = 3'd0,
                   S1_A = 3'd1,
                   S2_A = 3'd2,
                   S3_A = 3'd3,
                   DONE_A = 3'd4;

  reg [2:0] state_a, next_state_a;

  // Define states for g FSM
  localparam [2:0] IDLE_B = 3'd0,
                   S1_B = 3'd1,
                   S2_B = 3'd2,
                   S3_B = 3'd3,
                   DONE_B = 3'd4;

  reg [2:0] state_b, next_state_b;

  // f state transitions
  always @(posedge clk) begin
    if (resetn)
      state_a <= IDLE_A;
    else
      state_a <= next_state_a;
  end

  // f next state logic
  always @(*) begin
    case (state_a)
      IDLE_A: next_state_a = y ? S1_A : IDLE_A;
      S1_A: next_state_a = y ? S2_A : IDLE_A;
      S2_A: next_state_a = x ? S3_A : S2_A;
      S3_A: next_state_a = x ? DONE_A : S3_A;
      DONE_A: next_state_a = DONE_A;
      default: next_state_a = IDLE_A;
    endcase
  end

  // g state transitions
  always @(posedge clk) begin
    if (resetn)
      state_b <= IDLE_B;
    else
      state_b <= next_state_b;
  end

  // g next state logic
  always @(*) begin
    case (state_b)
      IDLE_B: next_state_b = y ? S1_B : IDLE_B;
      S1_B: next_state_b = y ? S2_B : IDLE_B;
      S2_B: next_state_b = x ? S3_B : S2_B;
      S3_B: next_state_b = x ? DONE_B : S3_B;
      DONE_B: next_state_b = DONE_B;
      default: next_state_b = IDLE_B;
    endcase
  end

  // Output assignments
  assign f = (state_a == DONE_A);
  assign g = (state_b == DONE_B);

endmodule

module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  // Define the states
  localparam [2:0] 
    IDLE    = 3'd0,
    LEFT    = 3'd1,
    RIGHT   = 3'd2,
    DOWN    = 3'd3,
    UP      = 3'd4,
    ERROR   = 3'd5,
    WAIT    = 3'd6;

  reg [2:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (resetn) begin
      current_state <= IDLE;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE: begin
        next_state = y ? WAIT : IDLE;
      end
      WAIT: begin
        if (!y)
          next_state = IDLE;
        else if (x)
          next_state = ERROR;
        else if (resetn)
          next_state = WAIT;
        else begin
          if (x && !y)
            next_state = LEFT;
          else if (x && y)
            next_state = RIGHT;
          else if (!x && y)
            next_state = DOWN;
          else
            next_state = UP;
        end
      end
      LEFT:   next_state = resetn ? LEFT : IDLE;
      RIGHT:  next_state = resetn ? RIGHT : IDLE;
      DOWN:   next_state = resetn ? DOWN : IDLE;
      UP:     next_state = resetn ? UP : IDLE;
      ERROR:  next_state = ERROR;
      default: next_state = IDLE;
    endcase
  end

  // Output logic
  assign f = (current_state == LEFT);
  assign g = (current_state == RIGHT);

endmodule

