  assign D1 = (x & ~Q0) | (~x & Q0);  // Q1 is XOR of x and Q0
  assign D2 = (~x & Q1) | (x & ~Q0 & Q1);  // Q2 is (x & ~Q0) | (~x & Q1)

  // Output logic
  assign z = (~x & ~Q0 & ~Q1) | (~x & ~Q0 & Q1);

  // Flip-flop updates
  always @(posedge clk) begin
    Q0 <= D0;
    Q1 <= D1;
    Q2 <= D2;
  end

