module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // One-hot decoding to current state index (0-9)
  wire [3:0] current_index = state[9:6];

  // Predefined indices for red, green, blue (example: R=0, G=1, B=2)
  localparam RED     = 4'd0;
  localparam GREEN   = 4'd1;
  localparam BLUE    = 4'd2;

  // Previous frame indices (assumed to be current state shifted left by 1)
  wire [3:0] prev_index = current_index << 1;

  // Compute component indices for previous frame
  wire [3:0] prev_red     = (prev_index == RED)    ? RED     : (prev_index - 4'd1);
  wire [3:0] prev_green   = (prev_index == GREEN)  ? GREEN   : (prev_index - 4'd1);
  wire [3:0] prev_blue    = (prev_index == BLUE)   ? BLUE    : (prev_index - 4'd1);

  // Determine component values for previous frame
  wire prev_red_active  = (prev_red == RED);
  wire prev_green_active= (prev_green == GREEN);
  wire prev_blue_active = (prev_blue == BLUE);

  // Compute hit signals for previous frame
  assign B3_next  = d  & prev_red_active;
  assign S_next = ack & prev_green_active;
  assign S1_next = done_counting  & prev_blue_active;

  // Current frame hit signals
  assign Count_next  = d  & (current_index == RED);
  assign Wait_next = ack & (current_index == GREEN);
  assign done = done_counting  & (current_index == BLUE);

  // First hit signal (OR of all components)
  assign counting = Count_next | Wait_next | done;

  // Total hit signal (previous + current)
  assign shift_ena = B3_next | S_next | S1_next | counting;

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // One-hot decoded current state
  wire [9:0] curr_decoded = state[9] ? 10'b0000000001 :
                           state[8] ? 10'b0000000010 :
                           state[7] ? 10'b0000000100 :
                           state[6] ? 10'b0000001000 :
                           state[5] ? 10'b0000010000 :
                           state[4] ? 10'b0000100000 :
                           state[3] ? 10'b0001000000 :
                           state[2] ? 10'b0010000000 :
                           state[1] ? 10'b0100000000 :
                           state[0] ? 10'b1000000000 :
                           10'b0000000000;

  // Stage 7: All bits set (OR of all curr_decoded bits)
  assign shift_ena = |curr_decoded;

  // Stage 6: Bits 3,4,5,6 (zero-indexed)
  assign S1_next = curr_decoded[3] | curr_decoded[4] | curr_decoded[5] | curr_decoded[6];

  // Stage 5: Bits 1,2,3,4,5,6
  assign S_next = curr_decoded[1] | curr_decoded[2] | curr_decoded[3] |
                 curr_decoded[4] | curr_decoded[5] | curr_decoded[6];

  // Stage 4: Bits 0,1,2,3,4,5,6
  assign B3_next = curr_decoded[0] | curr_decoded[1] | curr_decoded[2] |
                 curr_decoded[3] | curr_decoded[4] | curr_decoded[5] | curr_decoded[6];

  // Stage 3: Bits 0,1,2,3,4,5,7,8,9
  assign Count_next = curr_decoded[0] | curr_decoded[1] | curr_decoded[2] |
                 curr_decoded[3] | curr_decoded[4] | curr_decoded[5] |
                 curr_decoded[7] | curr_decoded[8] | curr_decoded[9];

  // Stage 2: Bits 0,1,2,3,4,6,7,8,9
  assign Wait_next = curr_decoded[0] | curr_decoded[1] | curr_decoded[2] |
                 curr_decoded[3] | curr_decoded[4] | curr_decoded[6] |
                 curr_decoded[7] | curr_decoded[8] | curr_decoded[9];

  // Stage 1: Bits 0,1,2,4,5,6,7,8,9
  assign done = curr_decoded[0] | curr_decoded[1] | curr_decoded[2] |
                 curr_decoded[4] | curr_decoded[5] | curr_decoded[6] |
                 curr_decoded[7] | curr_decoded[8] | curr_decoded[9];

  // Stage 0: Bits 0,2,4,5,6,8,9
  assign counting = curr_decoded[0] | curr_decoded[2] | curr_decoded[4] |
                 curr_decoded[5] | curr_decoded[6] | curr_decoded[8] |
                 curr_decoded[9];

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // One-hot decoding to current state bit (assuming state[9:0] where state[9] is MSB)
  wire current_bit = state[9];

  // Control signal assignments
  assign B3_next = ack;
  assign S_next = ack ? ~d : (current_bit ? d : 1'b1);
  assign S1_next = ack ? (current_bit ? d : 1'b1) : 1'b0;
  assign Count_next = (state[8] & done_counting) | (~state[8] & ~current_bit & done_counting);
  assign Wait_next = (state[7] & done_counting) | (~state[7] & ~current_bit & done_counting);
  assign done = state[6];
  assign counting = state[5];
  assign shift_ena = ack | (current_bit & d);

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // One-hot encoded state assuming state[9] is MSB and state[0] is LSB (10 bits)
  assign B3_next = state[9];
  assign S_next = state[8];
  assign S1_next = state[7] & d;
  assign Count_next = state[6] | (state[5] & done_counting);
  assign Wait_next = state[4] | (state[3] & done_counting);
  assign done = state[2];
  assign counting = state[1];
  assign shift_ena = state[0] | (state[1] & ack);

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // Current state definitions (one-hot encoding)
  localparam [9:0] RIF  = 10'b0000000001; // Register Input Fan-in
  localparam [9:0] ROM0 = 10'b0000000010; // Program Memory Bank 0
  localparam [9:0] ROM1 = 10'b0000000100; // Program Memory Bank 1
  localparam [9:0] MEM0 = 10'b0000001000; // Data Memory Bank 0
  localparam [9:0] MEM1 = 10'b0000010000; // Data Memory Bank 1
  localparam [9:0] WBR  = 10'b0000100000; // Write Back Register
  localparam [9:0] PC   = 10'b0001000000; // Program Counter
  localparam [9:0] HALT = 10'b0010000000; // Halt state

  // Next state calculation
  wire [9:0] next_PC = (state == ROM0) ? ROM1 :
                       (state == ROM1) ? ROM0 :
                       (state == MEM0) ? MEM1 :
                       (state == MEM1) ? MEM0 :
                       (state == WBR)  ? PC   :
                       (state == PC)   ? HALT :
                       state;

  // PC update control
  assign S1_next = (next_PC == HALT) && d;
  assign B3_next = (next_PC == PC) && d;

  // Memory read control for bank select
  assign shift_ena = (next_PC == MEM0) || (next_PC == MEM1);

  // Memory read enable (stall during read)
  assign S_next = (next_PC == MEM0) || (next_PC == MEM1);

  // Register file enables
  assign Count_next = (next_PC == RIF) || (next_PC == WBR);
  assign Wait_next = (next_PC == ROM0) || (next_PC == ROM1);

  // Write-back destination select
  assign done = (next_PC == WBR);
  assign counting = (next_PC == PC);

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     reg [16:1] A1, A2;
     reg [16:1] B1, B2;

     // Process A
     always @(posedge A[1] or posedge A[32]) begin
         if (A[32]) begin
             A1 <= 16'bz;
         end else begin
             A1 <= A[16:1];
         end
     end

     // Process B
     always @(posedge B[1] or posedge B[32]) begin
         if (B[32]) begin
             A2 <= 16'bz;
         end else begin
             A2 <= B[16:1];
         end
     end

     // Combine results
     assign S = {A2, A1};
     assign C32 = A1[1] & A2[1];

     // Handle Z state propagation
     assign S[32] = S[31] & S[30];
     assign S[31] = S[31] & S[29];
     assign S[30] = S[30] & S[28];
     assign S[29] = S[29] & S[27];
     assign S[28] = S[28] & S[26];
     assign S[27] = S[27] & S[25];
     assign S[26] = S[26] & S[24];
     assign S[25] = S[25] & S[23];
     assign S[24] = S[24] & S[22];
     assign S[23] = S[23] & S[21];
     assign S[22] = S[22] & S[20];
     assign S[21] = S[21] & S[19];
     assign S[20] = S[20] & S[18];
     assign S[19] = S[19] & S[17];
     assign S[18] = S[18] & S[16];
     assign S[17] = S[17] & S[15];
     assign S[16] = S[16] & S[14];
     assign S[15] = S[15] & S[13];
     assign S[14] = S[14] & S[12];
     assign S[13] = S[13] & S[11];
     assign S[12] = S[12] & S[10];
     assign S[11] = S[11] & S[9];
     assign S[10] = S[10] & S[8];
     assign S[9]  = S[9]  & S[7];
     assign S[8]  = S[8]  & S[6];
     assign S[7]  = S[7]  & S[5];
     assign S[6]  = S[6]  & S[4];
     assign S[5]  = S[5]  & S[3];
     assign S[4]  = S[4]  & S[2];
     assign S[3]  = S[3]  & S[1];
     assign S[2]  = S[2]  & A[32];
     assign S[1]  = S[1]  & A[31];

endmodule

module adder_32bit(A,B,S,C32);
