     // Buffer to store the concatenated output of C32 and B[1:0]
     reg [32:1] buffer;

     // Assign C32 as the LSB of A
     assign C32 = A[1];

     // Concatenate C32 and B[1:0] to form the buffer
     always @(*) begin
         buffer = {C32, B[1:0]};
     end

     // Assign the buffer to S
     assign S = buffer;

