module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     (* pad = 0, overlap = 0, dont_touch = 1 *) reg [32:1] shift_reg1;
     (* pad = 0, overlap = 0, dont_touch = 1 *) reg [32:1] shift_reg2;

     // Extract lower 16 bits and sign-extend to 33 bits for input 1
     wire [32:0] lower1_1 = { {17{A[15]}}, A[15:0] };
     // Extract lower 16 bits and sign-extend to 33 bits for input 2
     wire [32:0] lower1_2 = { {17{B[15]}}, B[15:0] };

     // Shift registers logic with self-loop and constant input 1
     always @(posedge C32 or posedge lower1_1[32]) begin
         if (lower1_1[32]) begin
             shift_reg1 <= 33'd1;
         end else begin
             shift_reg1 <= {shift_reg1[31:0], 1'b0};  // Shift left, fill LSB with 0
         end
     end

     (* pad = 0, overlap = 0, dont_touch = 1 *) reg [32:1] shift_reg2_const;
     // Predefined value for input 2's shift register
     always @(*) begin
         shift_reg2_const = 33'd2;
     end

     // Shift register 2 logic with self-loop and constant input 2
     always @(posedge C32 or posedge lower1_2[32]) begin
         if (lower1_2[32]) begin
             shift_reg2_const <= 33'd2;
         end else begin
             shift_reg2_const <= {shift_reg2_const[31:0], 1'b0};
         end
     end

     // Concatenate the two shift registers' outputs (lower 16 bits each)
     assign S = {shift_reg1[16:1], shift_reg2_const[16:1]};
     assign C32 = shift_reg1[32];  // MSB of input 1's shift register
 endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     reg [32:1] shift_reg_A;
     reg [32:1] shift_reg_B;

     wire [32:1] shifted_A = shift_reg_A << 1;
     wire [32:1] shifted_B = shift_reg_B << 1;
     wire [31:0] sign_extended_shifted_A = { {1{shifted_A[32]}}, shifted_A[31:0] };
     wire [31:0] sign_extended_shifted_B = { {1{shifted_B[32]}}, shifted_B[31:0] };
     wire [63:0] sum = sign_extended_shifted_A + sign_extended_shifted_B;
     wire [32:1] new_A = sum[63:32];
     wire new_sign = sum[63];

     always @(posedge A[1] or posedge B[1]) begin
         if (B[1]) begin
             shift_reg_A <= 32'b0;
             shift_reg_B <= 32'b0;
         end else begin
             shift_reg_A <= A;
             shift_reg_B <= B;
         end
     end

     assign S = new_A;
     assign C32 = new_sign;
endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     reg [16:1] A;
     reg [16:1] B;

     // Shift A and B registers on each clock edge
     always @(posedge A[1] or posedge B[1]) begin
         if (B[1]) begin
             A <= 16'h0001;
             B <= 16'h0001;
         end else begin
             A <= {A[15:1], 1'b0};  // Left shift A by 1
             B <= {B[15:1], 1'b0};  // Left shift B by 1
         end
     end

     // Compute the upper 2 bits of the 4-bit multiplier
     wire [1:0] M_upper = A[32:31];
     // Compute the lower 2 bits of the 32-bit multiplicand
     wire [1:0] y1 = B[1:0];
     // Calculate C32 as the product of M_upper and y1
     assign C32 = (M_upper * y1) % 2;

     // Concatenate the shifted B register with C32 to form S
     assign S = {B, C32};

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] G, P;
    wire [8:0] C;

    assign C[0] = cin;

    // Generate and propagate signals
    assign G = a & b;
    assign P = a ^ b;

    // Group carry computation
    assign C[1] = G[0] | (P[0] & C[0]);
    assign C[2] = G[1] | (P[1] & C[1]);
    assign C[3] = G[2] | (P[2] & C[2]);
    assign C[4] = G[3] | (P[3] & C[3]);
    assign C[5] = G[4] | (P[4] & C[4]);
    assign C[6] = G[5] | (P[5] & C[5]);
    assign C[7] = G[6] | (P[6] & C[6]);
    assign C[8] = G[7] | (P[7] & C[7]);

    // Sum bits calculation
    assign sum[0] = P[0] ^ C[0];
    assign sum[1] = P[1] ^ C[1];
    assign sum[2] = P[2] ^ C[2];
    assign sum[3] = P[3] ^ C[3];
    assign sum[4] = P[4] ^ C[4];
    assign sum[5] = P[5] ^ C[5];
    assign sum[6] = P[6] ^ C[6];
    assign sum[7] = P[7] ^ C[7];

    // Carry-out assignment
    assign cout = C[8];

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);
    wire [8:0] carry;
    assign carry[0] = cin;

    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin: adder_loop
            assign sum[i] = a[i] ^ b[i] ^ carry[i];
            assign carry[i+1] = (a[i] & b[i]) | (carry[i] & (a[i] ^ b[i]));
        end
    endgenerate

    assign cout = carry[8];
endmodule

module adder_8bit(
