    input cin, 
    output [7:0] sum, 
    output cout);
    wire [8:0] c;
    assign c[0] = cin;

    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin : adder_stage
            wire p, g;
            assign p = a[i] ^ b[i];
            assign g = a[i] & b[i];
