    wire [7:0] B;
    assign B[0] = b[0] | (~a[0] & ~cin);
    assign B[1] = b[1] | (~a[1] & ~B[0]);
    assign B[2] = b[2] | (~a[2] & ~B[1]);
    assign B[3] = b[3] | (~a[3] & ~B[2]);
    assign B[4] = b[4] | (~a[4] & ~B[3]);
    assign B[5] = b[5] | (~a[5] & ~B[4]);
    assign B[6] = b[6] | (~a[6] & ~B[5]);
    assign B[7] = b[7] | (~a[7] & ~B[6]);

    // Compute difference bits using XOR with borrow-in
    assign sum[0] = a[0] ^ cin;
    assign sum[1] = a[1] ^ B[0];
    assign sum[2] = a[2] ^ B[1];
    assign sum[3] = a[3] ^ B[2];
    assign sum[4] = a[4] ^ B[3];
    assign sum[5] = a[5] ^ B[4];
    assign sum[6] = a[6] ^ B[5];
    assign sum[7] = a[7] ^ B[6];

    // Borrow-out is the borrow-in of the MSB (B7)
    assign cout = B[7];
endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Determine if each input is valid (0-9)
    wire a_valid = (A <= 4'd9);
    wire b_valid = (B <= 4'd9);
    wire invalid = ~a_valid | ~b_valid;

    // Predefined valid sum and carry when both inputs are valid
    wire [3:0] valid_sum = {1'b0, A[3:2], A[1], A[0] + B[3:2], B[1], B[0]};
    wire [3:0] valid_carry = A[3] ^ B[3];

    // Calculate sum and carry using carry look-ahead logic
    wire [4:0] sum_full = {1'b0, A} + {1'b0, B} + Cin;
    wire [3:0] sum_partial = sum_full[3:0];
    wire carry_partial = sum_full[4];

    // Select between calculated and predefined values
    assign Sum = invalid ? valid_sum : sum_partial;
    assign Cout = invalid ? valid_carry : carry_partial;

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
