    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);
    wire [3:0] p, g;
    assign p = A ^ B;     // Propagate signals
    assign g = A & B;     // Generate signals

    // BCD correction logic
    wire correction_needed;
    assign correction_needed = (Sum > 9) || (Cout && (Sum >= 6));

    assign Sum = correction_needed ? (Sum + 4'd6) : Sum;
    assign Cout = correction_needed;

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
