    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Stage 1: Combine A and B with initial carry
    wire [4:0] stage1 = A + B + Cin;
    wire carry1 = (stage1 >= 5'd10) ? 1'b1 : 1'b0;
    wire [3:0] sum1 = (stage1 >= 5'd10) ? (stage1 - 4'd10) : stage1[3:0];

    // Stage 2: Adjust sum1 and carry1
    wire [4:0] stage2 = sum1 + carry1;
    wire carry2 = (stage2 >= 5'd10) ? 1'b1 : 1'b0;
    wire [3:0] sum2 = (stage2 >= 5'd10) ? (stage2 - 4'd10) : stage2[3:0];

    assign Sum = sum2;
    assign Cout = carry2;

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry (0 or 1)
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry (0 or 1)
);

    //阶段1：将val_0和val_1转换为直接的加法器输入（不考虑进位）
    wire [3:0] x1_direct = A;
    wire [3:0] y1_direct = B;

    //阶段2：计算阶段1的总和（可能超过4位）
    wire [4:0] sum1 = x1_direct + y1_direct + Cin;
    wire [3:0] sum1_mod = sum1[3:0];
    wire c1 = sum1[4]; //进位从阶段1的第五位

    //阶段3：如果进位c1存在，将sum1_mod和c1作为新的输入再次相加
    wire [4:0] sum2 = (c1 ? {1'b0, sum1_mod} : sum1_mod) + c1;

    //阶段4：输出结果
    assign Sum = sum2[3:0];
    assign Cout = sum2[4];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Stage 1: Adders with 1-cycle delay
    wire [3:0] stage1_sum;
    wire c1_0, c1_1, c1_2, c1_3;

    assign #1 c1_0 = A[0] ^ B[0] ^ Cin;
    assign stage1_sum[0] = A[0] ^ B[0] ^ Cin; // Sum bit

    assign #1 c1_1 = A[1] ^ B[1] ^ c1_0;
    assign stage1_sum[1] = A[1] ^ B[1] ^ c1_0; // Sum bit

    assign #1 c1_2 = A[2] ^ B[2] ^ c1_1;
    assign stage1_sum[2] = A[2] ^ B[2] ^ c1_1; // Sum bit

    assign #1 c1_3 = A[3] ^ B[3] ^ c1_2;
    assign stage1_sum[3] = A[3] ^ B[3] ^ c1_2; // Sum bit

    // Stage 2: Correction and output with 1-cycle delay
    wire [3:0] stage2_sum;
    wire c2_0, c2_1, c2_2, c2_3;

    assign #1 c2_0 = (stage1_sum[0] >= 5) ? 1'b1 : 1'b0;
    assign stage2_sum[0] = stage1_sum[0] ^ c2_0;

    assign #1 c2_1 = (stage1_sum[1] >= 5 + c2_0) ? 1'b1 : 1'b0;
    assign stage2_sum[1] = stage1_sum[1] ^ c2_1;

    assign #1 c2_2 = (stage1_sum[2] >= 5 + c2_0 + c2_1) ? 1'b1 : 1'b0;
    assign stage2_sum[2] = stage1_sum[2] ^ c2_2;

    assign #1 c2_3 = (stage1_sum[3] >= 5 + c2_0 + c2_1 + c2_2) ? 1'b1 : 1'b0;
    assign stage2_sum[3] = stage1_sum[3] ^ c2_3;

    assign Sum = stage2_sum;
    assign Cout = c2_3;

endmodule

