module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);
    // Declare intermediate wires for individual operations
    wire [3:0] xor_intermediate;
    wire [3:0] and_intermediate;
    wire [3:0] or_intermediate;
    wire [4:0] carry;  // 5-bit carry for four adder stages

    // 4-bit XNOR using 4-bit XOR followed by AND
    assign xor_intermediate = A ^ B;
    assign and_intermediate = xor_intermediate & xor_intermediate;

    // 4-bit OR using 4-bit AND followed by OR reduction
    assign or_intermediate = ~(and_intermediate & and_intermediate);

    // 4-bit full adder with carry chain
    assign carry[0] = 1'b0;  // Initial carry-in is 0
    assign carry[1] = (A[0] & B[0]) | ((A[0] ^ B[0]) & carry[0]);
    assign A_equal[0] = (A[0] ^ B[0]) ^ carry[0];
    assign carry[2] = (A[1] & B[1]) | ((A[1] ^ B[1]) & carry[1]);
    assign A_equal[1] = (A[1] ^ B[1]) ^ carry[1];
    assign carry[3] = (A[2] & B[2]) | ((A[2] ^ B[2]) & carry[2]);
    assign A_equal[2] = (A[2] ^ B[2]) ^ carry[2];
    assign carry[4] = (A[3] & B[3]) | ((A[3] ^ B[3]) & carry[3]);
    assign A_equal[3] = (A[3] ^ B[3]) ^ carry[3];

    // Assign final outputs from intermediate results
    assign A_greater = |or_intermediate;  // OR of all OR intermediate bits
    assign A_less = carry[4];         // Final carry-out from adder
endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);
    // Declare intermediate wires for individual operations
    wire [3:0] and_ab;
    wire [3:0] xor_ab;
    wire [3:0] or_ab;
    wire [3:0] nand_ab;
    wire [3:0] not_a;

    // Perform AND, OR, XOR, NAND, and NOT operations for each bit
    and(and_ab[0], A[0], B[0]);
    or(or_ab[0], A[0], B[0]);
    xor(xor_ab[0], A[0], B[0]);
    nand(nand_ab[0], A[0], B[0]);
    not(not_a[0], A[0]);

    // Repeat for other bits (1-3)
    and(and_ab[1], A[1], B[1]);
    or(or_ab[1], A[1], B[1]);
    xor(xor_ab[1], A[1], B[1]);
    nand(nand_ab[1], A[1], B[1]);
    not(not_a[1], A[1]);

    and(and_ab[2], A[2], B[2]);
    or(or_ab[2], A[2], B[2]);
    xor(xor_ab[2], A[2], B[2]);
    nand(nand_ab[2], A[2], B[2]);
    not(not_a[2], A[2]);

    and(and_ab[3], A[3], B[3]);
    or(or_ab[3], A[3], B[3]);
    xor(xor_ab[3], A[3], B[3]);
    nand(nand_ab[3], A[3], B[3]);
    not(not_a[3], A[3]);

    // Combine intermediate results using AND, OR, XOR, NAND, NOT
    assign A_greater = (and_ab[0] | xor_ab[1]) ^ (or_ab[2] & nand_ab[3]);
    assign A_equal = ~(and_ab[1] ^ or_ab[3]);
    assign A_less = (xor_ab[2] & not_a[0]) | (nand_ab[3] & xor_ab[1]);

endmodule

module comparator_4bit(
