    wire eq1 = (A[1] == B[1]);
    wire eq0 = (A[0] == B[0]);

    // Calculate 'A_equal' as the AND of all comparison results
    assign A_equal = eq3 & eq2 & eq1 & eq0;

    // Compute borrow signals for each bit (B3, B2, B1, B0)
    wire B3 = (~A[3]) & B[3];
    wire B2 = (~A[2]) & B[2];
    wire B1 = (~A[1]) & B[1];
    wire B0 = (~A[0]) & B[0];

