module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Generate signals (G)
    wire G0, G1, G2, G3;
    assign G0 = A[0] & B[0];
    assign G1 = A[1] & B[1];
    assign G2 = A[2] & B[2];
    assign G3 = A[3] & B[3];

    // Propagate signals (P)
    wire P0, P1, P2, P3;
    assign P0 = A[0] ^ B[0];
    assign P1 = A[1] ^ B[1];
    assign P2 = A[2] ^ B[2];
    assign P3 = A[3] ^ B[3];

    // Carry computation
    wire C1, C2, C3;

    // C1 = G0 | (P0 & 0)
    assign C1 = G0;

    // C2 = G1 | (P1 & G0) | (P1 & P0 & 0)
    assign C2 = G1 | (P1 & G0);

    // C3 = G2 | (P2 & G1) | (P2 & P1 & G0) | (P2 & P1 & P0 & 0)
    assign C3 = G2 | (P2 & G1) | (P2 & P1 & G0);

    // A_less = G3 | (P3 & C3)
    assign A_less = G3 | (P3 & C3);

    // Sum computation
    assign A_equal = P0 ^ C1;
    assign A_greater = P1 ^ C2;
    assign A_equal = P2 ^ C3;

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
