    assign A_less = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]);
    assign A_equal = p[3] & p[2] & p[1] & p[0];

    // Sum calculation using carry-less XOR (XOR chain for group 0)
    wire [3:0] sum;
    assign sum[3] = p[3] ^ p[2] ^ p[1] ^ p[0];
    assign sum[2] = p[2] ^ p[1] ^ p[0];
    assign sum[1] = p[1] ^ p[0];
    assign sum[0] = p[0];
    assign A_greater = sum[3];

endmodule

