module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] stage1, stage2;

// First stage flip-flops
always @(posedge clk_a or negedge arstn) begin
    if (!arstn) begin
        stage1 <= 4'b0;
    end else begin
        stage1 <= {data_en, brstn, data_in[2:1]};
    end
end

// Second stage flip-flops
always @(posedge clk_a or negedge arstn) begin
    if (!arstn) begin
        stage2 <= 4'b0;
    end else if (clk_b) begin
        stage2 <= {data_en, brstn, data_in};
    end
end

// Output update logic
always @(posedge clk_a or negedge arstn) begin
    if (!arstn) begin
        dataout <= 4'b0;
    end else if (clk_b) begin
        dataout <= stage2;
    end
end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] data_a_reg;
reg data_b_reg;
reg sync_en_1, sync_en_2;

// Capture data_in and data_en in clk_a domain
always @(posedge clk_a or negedge brstn) begin
	if (!brstn) begin
		data_a_reg <= 4'b0;
		data_b_reg <= 1'b0;
	end
	else begin
		if (arstn) begin
			data_a_reg <= data_in;
			data_b_reg <= data_en;
		end
		else begin
			data_a_reg <= data_a_reg;
			data_b_reg <= data_b_reg;
	 end
end

// Two-stage synchronizer for data_en in clk_b domain
always @(posedge clk_b or negedge brstn) begin
	if (!brstn) begin
		sync_en_1 <= 1'b0;
		sync_en_2 <= 1'b0;
	end
	else begin
		sync_en_1 <= data_en;
		sync_en_2 <= sync_en_1;
	end
end

// Update dataout when data_en is synchronized
always @(posedge clk_b or negedge brstn) begin
	if (!brstn) begin
		dataout <= 4'b0;
	end
	else begin
		if (sync_en_2) begin
			dataout <= data_a_reg;
		end
	end
end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	reg [3:0] des_reg;
	reg [3:0] core_reg;

	// Data Extraction Stage (clk_a domain)
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			des_reg <= 4'b0;
		end else begin
			des_reg <= data_en ? data_in : des_reg;
		end
	end

	// Pipeline Adaptation Stage (clk_b domain)
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			core_reg <= 4'b0;
		end else begin
			core_reg <= des_reg;
		end
	end

	// Output Stage (clk_b domain)
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout <= 4'b0;
		end else begin
			dataout <= core_reg;
		end
	end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Synchronize asynchronous inputs
	reg [3:0] data_sync;
	reg vsync_sync, vsync_sync_prev;

	// Synchronization flip-flops
	always @(posedge clk_b or negedge clk_a) begin
		if (!clk_a) begin
			data_sync <= 4'b0;
			vsync_sync <= 1'b0;
			vsync_sync_prev <= 1'b0;
		end else begin
			data_sync <= data_in;
			vsync_sync <= data_en;
			vsync_sync_prev <= vsync_sync;
		end
	end

	// Edge detection for data_en
	wire vsync_edge = vsync_sync && !vsync_sync_prev;

	// Output update logic
	always @(posedge clk_b or negedge clk_a) begin
		if (!clk_a) begin
			dataout <= 4'b0;
		end else if (brstn) begin
			dataout <= data_sync;
		end else if (vsync_edge) begin
			dataout <= data_sync;
		end
	end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	reg [3:0] stage1, stage2;

	// First stage flip-flops
	always @(posedge clk_b or negedge clk_a) begin
		if (!clk_a) begin
			stage1 <= 4'b0;
		end else if (brstn) begin
			stage1 <= data_in;
		end
	end

	// Second stage flip-flops
	always @(posedge clk_b or negedge clk_a) begin
		if (!clk_a) begin
			stage2 <= 4'b0;
		end else if (arstn) begin
			stage2 <= stage1;
		end
	end

	// Output assignment with reset and clock drive
	always @(posedge clk_b or negedge clk_a) begin
		if (!clk_a) begin
			dataout <= 4'b0;
		end else if (data_en) begin
			dataout <= stage2;
		end
	end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

parameter s0 = 3'b000,
          s1 = 3'b001,
          s2 = 3'b010,
          s3 = 3'b011,
          s4 = 3'b100;

reg [2:0] current_state, next_state;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        current_state <= s0;
    end else begin
        current_state <= next_state;
    end
end

always @(*) begin
    case (current_state)
        s0: next_state = IN ? s1 : s0;
        s1: next_state = IN ? s1 : s2;
        s2: next_state = IN ? s3 : s0;
        s3: next_state = IN ? s4 : s2;
        s4: next_state = IN ? s1 : s2;
        default: next_state = s0;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        MATCH <= 1'b0;
    end else begin
        MATCH <= (current_state == s4);
    end
end

endmodule

module fsm(IN,MATCH,CLK,RST);
    input IN,CLK,RST;
    output reg MATCH;

    // Main state register (one-hot encoding)
    reg [4:0] main_state;
    localparam [4:0] IDLE = 5'b00001,
                     S1   = 5'b00010,
                     S2   = 5'b00100,
                     S3   = 5'b01000,
                     T    = 5'b10000;

    // Error register (1-bit)
    reg error_reg;

    // Main state transitions (synchronous to CLK)
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            main_state <= IDLE;
        end else begin
            case (main_state)
                IDLE: main_state <= IN ? S1 : IDLE;
                S1:   main_state <= IN ? S2 : IDLE;
                S2:   main_state <= IN ? S3 : IDLE;
                S3:   main_state <= IN ? T : IDLE;
                T:    main_state <= IDLE;
                default: main_state <= IDLE;
            endcase
        end
    end

    // Error detection (synchronous to RST)
    always @(posedge RST) begin
        error_reg <= (main_state == S3) && (IN == 0);
    end

    // Output assignment
    always @(*) begin
        MATCH = error_reg;
    end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [1:0] state, next_state;
parameter S0 = 2'b00,
          S1 = 2'b01,
          S2 = 2'b10,
          S3 = 2'b11;

reg [1:0] count0, count1;
parameter MAX0 = 2'd2;
parameter MAX1 = 2'd1;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
        count0 <= 0;
        count1 <= 0;
    end else begin
        state <= next_state;
        if (state == S0) begin
            count0 <= (count0 == MAX0) ? 0 : count0 + 1;
        end else if (state == S1) begin
            count1 <= (count1 == MAX1) ? 0 : count1 + 1;
        end
    end
end

always @(*) begin
    next_state = state;
    case (state)
        S0: begin
            if (count0 == MAX0) begin
                if (IN) begin
                    next_state = S1;
                end else begin
                    next_state = S0;
                end
            end
        end
        S1: begin
            if (count1 == MAX1) begin
                next_state = IN ? S0 : S3;
            end
        end
        S3: begin
            if (count1 == MAX1) begin
                next_state = S0;
            end
        end
        default: next_state = S0;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        MATCH <= 0;
    end else begin
        MATCH <= (state == S3) && (count1 == MAX1);
    end
end

endmodule

module fsm(IN,MATCH,CLK,RST);
    input IN,CLK,RST;
    output reg MATCH;

    // Define states
    parameter zero = 3'b000,
              one = 3'b001,
              two = 3'b010,
              three = 3'b011,
              four = 3'b100;

    reg [2:0] current_state, next_state;
    reg [2:0] counter;

    // State transition and counter logic
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= zero;
            counter <= 3'b0;
        end else begin
            current_state <= next_state;

            // Update counter based on current state
            if (current_state == one)
                counter <= counter + 1;
            else
                counter <= 3'b0;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            zero:   next_state = (IN) ? one : zero;
            one:    next_state = (counter == 3'd6) ? two : one;
            two:    next_state = (IN) ? two : three;
            three:  next_state = (IN) ? four : three;
            four:   next_state = (IN) ? four : zero;
            default: next_state = zero;
        endcase
    end

    // Output logic
    always @(posedge CLK or posedge RST) begin
        if (RST)
            MATCH <= 1'b0;
        else
            MATCH <= (current_state == four);
    end
endmodule

module fsm(IN,MATCH,CLK,RST);
