output reg MATCH;

// Define states
localparam [2:0] 
    S_RESET = 3'd0,
    S_1     = 3'd1,
    S_11    = 3'd2,
    S_110   = 3'd3,
    S_1101  = 3'd4,
    S_11010 = 3'd5;

reg [2:0] current_state, next_state;

// State register with synchronous reset
always @(posedge CLK or posedge RST) begin
    if (RST) current_state <= S_RESET;
    else current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S_RESET: next_state = IN ? S_1 : S_RESET;
        S_1:     next_state = IN ? S_11 : S_RESET;
        S_11:    next_state = IN ? S_11 : S_110;
        S_110:   next_state = IN ? S_1101 : S_RESET;
        S_1101:  next_state = IN ? S_11 : S_11010;
        S_11010: next_state = IN ? S_1 : S_RESET;
        default: next_state = S_RESET;
    endcase
end

// Output logic (Moore style)
always @(*) begin
    MATCH = (current_state == S_11010);
end

endmodule

