module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     reg [2:0] r_Specimen;
     reg [2:0] r_BinarySpecimen;

     // Combinational assignment for sequence_detected
     assign sequence_detected = r_BinarySpecimen[2];

     // Sequential logic for r_Specimen
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             r_Specimen <= 3'b0;
         end else begin
             case (r_Specimen)
                 3'b000: r_Specimen <= data_in ? 3'b001 : 3'b000;
                 3'b001: r_Specimen <= data_in ? 3'b010 : 3'b000;
                 3'b010: r_Specimen <= data_in ? 3'b011 : 3'b001;
                 3'b011: r_Specimen <= data_in ? 3'b011 : 3'b010;
                 default: r_Specimen <= 3'b000;
             endcase
         end
     end

     // Sequential logic for r_BinarySpecimen
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             r_BinarySpecimen <= 3'b0;
         end else begin
             case (r_BinarySpecimen)
                 3'b000: r_BinarySpecimen <= 3'b001;
                 3'b001: r_BinarySpecimen <= 3'b010;
                 3'b010: r_BinarySpecimen <= 3'b011;
                 3'b011: r_BinarySpecimen <= 3'b000;
                 default: r_BinarySpecimen <= 3'b000;
             endcase
         end
     end

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     parameter [2:0] S0 = 3'b000,
                     S1 = 3'b001,
                     S2 = 3'b010,
                     S3 = 3'b011,
                     S4 = 3'b100;

     reg [2:0] current_state, next_state;

     always @(posedge clk or negedge rst_n) begin
         if (!rst_n)
             current_state <= S0;
         else
             current_state <= next_state;
     end

     always @(*) begin
         case (current_state)
             S0: next_state = data_in ? S1 : S0;
             S1: next_state = data_in ? S1 : S2;
             S2: next_state = data_in ? S1 : S3;
             S3: next_state = data_in ? S4 : S0;
             S4: next_state = data_in ? S1 : S2;
             default: next_state = S0;
         endcase
     end

     assign sequence_detected = (current_state == S4);

endmodule

